/**
 * Pure types of the observatory: the snapshot one fold over every persisted
 * session produces, the published row with the honest column set, the ranking
 * an experiment verdict earns, and the two faces of one rendered publication.
 *
 * @module @deepseek-ai/dsh-observatory/types
 */

import type { EnvironmentId, EnvironmentRunModel } from '@deepseek-ai/dsh-environments/types'
import type { ExperimentResult, ExperimentVerdict } from '@deepseek-ai/dsh-experiments/types'
import type { ScoreboardRow, ScorekeeperSkip } from '@deepseek-ai/dsh-scorekeeper/types'
import type { CertificateIsolation, RunExecutor } from '@deepseek-ai/dsh-verification/types'

/** Self-declared payload version of the JSON document this build renders. */
export const OBSERVATORY_DOCUMENT_VERSION = 1

/**
 * What a snapshot kept out of its public rows, counted rather than hidden: a
 * row that disappears without a count inflates every rate computed from the
 * rest. A row withheld for both reasons is counted under its district, which is
 * the reason checked first.
 */
export interface ObservatoryWithheld {
  /** Districts the deployment withholds, as configured. */
  readonly districts: readonly string[]
  /** Rows dropped because their district is withheld. */
  readonly districtRows: number
  /** Sessions in those rows, run and errored alike. */
  readonly districtSessions: number
  /** Rows dropped because their environment is held out. */
  readonly heldOutRows: number
  /** Sessions in those rows. */
  readonly heldOutSessions: number
}

/** What a caller hands one fold beside the persisted logs. */
export interface ObservatorySnapshotRequest {
  /**
   * Experiment results the caller holds from its own runs. No session event
   * carries an `ExperimentResult`, so a fold that is handed none publishes no
   * ranking; the snapshot keeps only the results whose two arm routes both
   * appear in its published rows.
   */
  readonly experiments?: readonly ExperimentResult[]
}

/** One fold over every persisted session, before rendering decides what it shows. */
export interface ObservatorySnapshot {
  /** Scoreboard rows that survived withholding, in the scorekeeper's fold order. */
  readonly rows: readonly ScoreboardRow[]
  /** What withholding removed from those rows. */
  readonly withheld: ObservatoryWithheld
  /** Experiment results whose two arm routes both appear in {@link rows}; empty publishes no ranking. */
  readonly experiments: readonly ExperimentResult[]
  /** Session headers the fold read. */
  readonly sessions: number
  /** Folded sessions whose log carries no `environment/run` stamp, so no row can name their cell. */
  readonly unstamped: number
  /** Sessions that could not be read or folded. */
  readonly skipped: readonly ScorekeeperSkip[]
  /** Epoch milliseconds at which the fold ran. */
  readonly foldedAt: number
  /** Newest `createdAt` among the session headers the fold read, absent when the store held none. */
  readonly newestSessionAt?: number
  /** Batch refresh interval the page names, milliseconds. */
  readonly refreshIntervalMs: number
}

/**
 * Tamper status of one published row. `not-instrumented` is a row whose
 * sessions recorded no run, so no verdict states whether the check-owned files
 * changed; `tampered` is a row at least one of whose runs found them changed.
 */
export type ObservatoryTamper = 'not-instrumented' | 'tampered' | 'none'

/**
 * One published row: the honest column set, with the publication rules already
 * applied. `resolved` and `parity` are two fields and stay two — neither is
 * ever computed from the other, and no field merges them.
 */
export interface ObservatoryPublishedRow {
  readonly provider: string
  readonly model: string
  readonly environmentId: EnvironmentId
  readonly environmentKind: string
  /** District the row's sessions were stamped with, absent for a row outside every district. */
  readonly district?: string
  readonly heldOut: boolean
  readonly isolation: CertificateIsolation
  /** Executors of the row's certificates; empty for a row that certified nothing. */
  readonly certificateExecutors: readonly RunExecutor[]
  /** Composition digest every session of the row states, absent when the page shows `pending`. */
  readonly compositionSha256?: string
  readonly tamper: ObservatoryTamper
  /** Sessions of the row whose last recorded run carried the `tampered` verdict. */
  readonly tampered: number
  /** Sessions that recorded at least one run. */
  readonly runs: number
  /** Sessions that ended without recording one. */
  readonly errors: number
  /** Sessions holding a certificate. */
  readonly certified: number
  /** `certified / runs`: the certificate rate under its own name, `0` without runs. */
  readonly resolved: number
  /** Mean weighted pass rate over the row's sessions that measured cases, absent when none did. */
  readonly parity?: number
  /** Mean cost of the row's certified sessions, absent unless {@link pricingDigest} names the one table that priced them. */
  readonly costEurPerCertified?: number
  /** The single pricing digest that priced the row, absent when the row carries none or more than one. */
  readonly pricingDigest?: string
}

/** One published ranking: an experiment's frozen plan, its two arms, and its verdict. */
export interface ObservatoryRanking {
  /** Content digest of the frozen plan; both arm groups carry it. */
  readonly digest: string
  /** Model route of the reference arm. */
  readonly baseline: EnvironmentRunModel
  /** Model route of the arm under test. */
  readonly candidate: EnvironmentRunModel
  /** Certificate-rate delta over every paired repetition. */
  readonly delta: number
  readonly verdict: ExperimentVerdict
}

/**
 * The JSON face of one publication. A stale document carries no row and no
 * ranking at all, so a consumer reading it cannot render a number the page
 * refused to show.
 */
export interface ObservatoryDocument {
  readonly version: typeof OBSERVATORY_DOCUMENT_VERSION
  /** Whether the newest folded session is older than the configured staleness threshold. */
  readonly stale: boolean
  /** Epoch milliseconds at which the fold ran. */
  readonly foldedAt: number
  /** Newest `createdAt` among the folded session headers, absent when the store held none. */
  readonly newestSessionAt?: number
  /** Batch refresh interval the page names, milliseconds. */
  readonly refreshIntervalMs: number
  /** Age of the newest folded session past which this document goes stale, milliseconds. */
  readonly staleAfterMs: number
  /** Published rows, empty for a stale document. */
  readonly rows: readonly ObservatoryPublishedRow[]
  /** What withholding removed; stated in both states, because a withheld row is a fact about the fold. */
  readonly withheld: ObservatoryWithheld
  /** Published rankings, empty for a stale document and for a fold carrying no experiment verdict. */
  readonly rankings: readonly ObservatoryRanking[]
}

/** Both faces of one publication, rendered from one snapshot at one instant. */
export interface ObservatoryPage {
  /** Self-contained HTML document; it references no external resource. */
  readonly html: string
  /** The same publication as data. */
  readonly json: ObservatoryDocument
}

/**
 * The publication rules as pure functions: which rows a fold may withhold,
 * which experiment verdicts a fold may rank, when a publication goes stale, and
 * what one row may state once those rules have run.
 *
 * Every rule here is fixed rather than configured. A deployment states which
 * districts it withholds, how stale is stale, and how often it refolds; it does
 * not state whether a cost may be published without the digest that priced it,
 * whether `resolved` may stand in for `parity`, or whether a ranking may appear
 * without a verdict, because those are what the page means.
 *
 * @module @deepseek-ai/dsh-observatory/publish
 */

import type { ExperimentResult } from '@deepseek-ai/dsh-experiments/types'
import type { ScoreboardRow } from '@deepseek-ai/dsh-scorekeeper/types'
import { OBSERVATORY_DOCUMENT_VERSION } from './types.ts'
import type {
  ObservatoryDocument,
  ObservatoryPublishedRow,
  ObservatoryRanking,
  ObservatorySnapshot,
  ObservatoryTamper,
} from './types.ts'

/** The districts and held-out split one fold keeps out of its public rows. */
export interface WithholdRule {
  /** Districts whose rows never reach the public page. */
  readonly districts: readonly string[]
  /** Whether held-out rows are withheld as well. */
  readonly heldOut: boolean
}

/** One fold's rows split into what it publishes and what it withheld, with the counts. */
export interface WithholdSplit {
  readonly published: readonly ScoreboardRow[]
  readonly districtRows: number
  readonly districtSessions: number
  readonly heldOutRows: number
  readonly heldOutSessions: number
}

/** Sessions one row folded, the errored ones included. */
function sessionsOf(row: ScoreboardRow): number {
  return row.runs + row.errors
}

/**
 * Split scoreboard rows into the published ones and the withheld counts. A row
 * withheld for both reasons is counted under its district, which is checked
 * first; the row key carries both dimensions, so every session of a withheld
 * row is withheld and no withheld session can reach a published row.
 * @param rows - every row the scoreboard folded, in fold order.
 * @param rule - the districts and held-out split to withhold.
 * @returns the published rows in fold order, and the rows and sessions dropped per reason.
 */
export function withhold(rows: readonly ScoreboardRow[], rule: WithholdRule): WithholdSplit {
  const published: ScoreboardRow[] = []
  let districtRows = 0
  let districtSessions = 0
  let heldOutRows = 0
  let heldOutSessions = 0
  for (const row of rows) {
    if (row.district !== undefined && rule.districts.includes(row.district)) {
      districtRows += 1
      districtSessions += sessionsOf(row)
      continue
    }
    if (rule.heldOut && row.heldOut) {
      heldOutRows += 1
      heldOutSessions += sessionsOf(row)
      continue
    }
    published.push(row)
  }
  return { published, districtRows, districtSessions, heldOutRows, heldOutSessions }
}

/** The `provider/model` key one route is matched by. */
function routeKey(provider: string, model: string): string {
  return `${provider}�${model}`
}

/**
 * Keep the experiment results whose two arm routes both appear in the published
 * rows. A verdict about a route the page withholds or never folded publishes no
 * ranking, so a ranking is never the only evidence of a session.
 * @param experiments - the results a caller holds from its own runs.
 * @param rows - the published rows, whose routes are the ones a ranking may name.
 * @returns the rankable results in caller order.
 */
export function rankable(
  experiments: readonly ExperimentResult[],
  rows: readonly ScoreboardRow[],
): readonly ExperimentResult[] {
  const routes = new Set(rows.map(row => routeKey(row.provider, row.model)))
  return experiments.filter((experiment) => {
    const { baseline, candidate } = experiment.arms
    return routes.has(routeKey(baseline.model.provider, baseline.model.model))
      && routes.has(routeKey(candidate.model.provider, candidate.model.model))
  })
}

/** The tamper status of one row: no verdict at all, at least one tamper, or none. */
function tamperOf(row: ScoreboardRow): ObservatoryTamper {
  if (row.runs === 0) return 'not-instrumented'
  return row.tampered > 0 ? 'tampered' : 'none'
}

/**
 * The cost fields one row may publish. Cost travels with the digest that priced
 * it and only when exactly one table priced the row: a row priced under two
 * tables states a sum across pricing tables, which is not a price.
 */
function costOf(row: ScoreboardRow): Pick<ObservatoryPublishedRow, 'costEurPerCertified' | 'pricingDigest'> {
  const [digest, ...rest] = row.pricingDigests
  if (digest === undefined || rest.length > 0 || row.costEurPerCertified === undefined) return {}
  return { costEurPerCertified: row.costEurPerCertified, pricingDigest: digest }
}

/**
 * Apply the row-level publication rules to one scoreboard row.
 * @param row - one published scoreboard row.
 * @returns the honest column set, with the cost and tamper rules already applied.
 */
export function publishRow(row: ScoreboardRow): ObservatoryPublishedRow {
  return {
    provider: row.provider,
    model: row.model,
    environmentId: row.environmentId,
    environmentKind: row.environmentKind,
    ...row.district === undefined ? {} : { district: row.district },
    heldOut: row.heldOut,
    isolation: row.isolation,
    certificateExecutors: row.certificateExecutors,
    ...row.compositionSha256 === undefined ? {} : { compositionSha256: row.compositionSha256 },
    tamper: tamperOf(row),
    tampered: row.tampered,
    runs: row.runs,
    errors: row.errors,
    certified: row.certified,
    resolved: row.certificateRate,
    ...row.parity === undefined ? {} : { parity: row.parity },
    ...costOf(row),
  }
}

/** One ranking from one experiment result. */
function publishRanking(experiment: ExperimentResult): ObservatoryRanking {
  return {
    digest: experiment.digest,
    baseline: experiment.arms.baseline.model,
    candidate: experiment.arms.candidate.model,
    delta: experiment.delta,
    verdict: experiment.verdict,
  }
}

/**
 * Whether a snapshot is too old to show numbers. A fold that read no session is
 * stale by the same rule: it has nothing whose age could be current.
 * @param snapshot - the fold to age.
 * @param now - epoch milliseconds the publication is rendered at.
 * @param staleAfterMs - age of the newest folded session past which the page shows the notice instead.
 * @returns `true` when the newest folded session is older than the threshold, or when none was folded.
 */
export function isStale(snapshot: ObservatorySnapshot, now: number, staleAfterMs: number): boolean {
  const newest = snapshot.newestSessionAt
  return newest === undefined || now - newest > staleAfterMs
}

/**
 * Build the JSON face of one publication.
 * @param snapshot - the fold to publish.
 * @param now - epoch milliseconds the publication is rendered at.
 * @param staleAfterMs - the staleness threshold this deployment configured.
 * @returns the document; a stale one carries no row and no ranking, and keeps the withheld counts.
 */
export function publishDocument(
  snapshot: ObservatorySnapshot,
  now: number,
  staleAfterMs: number,
): ObservatoryDocument {
  const stale = isStale(snapshot, now, staleAfterMs)
  return {
    version: OBSERVATORY_DOCUMENT_VERSION,
    stale,
    foldedAt: snapshot.foldedAt,
    ...snapshot.newestSessionAt === undefined ? {} : { newestSessionAt: snapshot.newestSessionAt },
    refreshIntervalMs: snapshot.refreshIntervalMs,
    staleAfterMs,
    rows: stale ? [] : snapshot.rows.map(publishRow),
    withheld: snapshot.withheld,
    rankings: stale ? [] : snapshot.experiments.map(publishRanking),
  }
}

