/**
 * The publication rules as they decide what a page may state: what withholding
 * removes and what it counts, when a fold goes stale, which verdicts may be
 * ranked, and which figures one row may publish.
 */

import { describe, expect, it } from 'vitest'
import { isStale, publishDocument, publishRow, rankable, withhold } from '@deepseek-ai/dsh-observatory'
import { experiment, row, snapshot } from './row.ts'

const DIGEST = 'a'.repeat(64)
const OTHER_DIGEST = 'b'.repeat(64)
const COMPOSITION = 'c'.repeat(64)

const WITHHOLD_WORKSHOP = { districts: ['workshop'], heldOut: true }

describe('withhold', () => {
  it('drops the withheld districts and the held-out split from the public rows and counts both', () => {
    const split = withhold([
      row({ district: 'workshop', runs: 3, errors: 1 }),
      row({ heldOut: true, runs: 2, errors: 2 }),
      row({ district: 'proving-ground', runs: 2, errors: 0 }),
      row({ runs: 1, errors: 0 }),
    ], WITHHOLD_WORKSHOP)
    expect(split.published.map(published => published.district)).toEqual(['proving-ground', undefined])
    expect(split).toMatchObject({
      districtRows: 1,
      districtSessions: 4,
      heldOutRows: 1,
      heldOutSessions: 4,
    })
  })

  it('counts a row withheld for both reasons under its district alone', () => {
    const split = withhold([row({ district: 'workshop', heldOut: true, runs: 2, errors: 0 })], WITHHOLD_WORKSHOP)
    expect(split.published).toEqual([])
    expect(split).toMatchObject({ districtRows: 1, districtSessions: 2, heldOutRows: 0, heldOutSessions: 0 })
  })

  it('publishes the held-out split when the deployment does not withhold it', () => {
    const split = withhold([row({ heldOut: true }), row({ district: 'workshop' })], { districts: [], heldOut: false })
    expect(split.published.map(published => published.heldOut)).toEqual([true, false])
    expect(split).toMatchObject({ districtRows: 0, heldOutRows: 0 })
  })
})

describe('isStale', () => {
  it('switches at the exact threshold and treats a fold that read no session as stale', () => {
    const current = snapshot({ newestSessionAt: 1000 })
    expect(isStale(current, 1000 + 60_000, 60_000)).toBe(false)
    expect(isStale(current, 1000 + 60_001, 60_000)).toBe(true)
    const { newestSessionAt: _absent, ...empty } = current
    expect(isStale(empty, 1000, 60_000)).toBe(true)
  })
})

describe('publishRow', () => {
  it('publishes the certificate rate as resolved and the weighted pass rate as parity, never one as the other', () => {
    const published = publishRow(row({ runs: 4, certified: 1, certificateRate: 0.25, parity: 0.75 }))
    expect(published.resolved).toBe(0.25)
    expect(published.parity).toBe(0.75)
    // Nothing on the published row merges the two, and neither is computed from the other.
    expect(Object.values(published)).not.toContain(0.5)
  })

  it('publishes no parity for a row whose sessions measured no cases', () => {
    expect(publishRow(row())).not.toHaveProperty('parity')
  })

  it('publishes the cost only beside the one pricing digest that priced the row', () => {
    const priced = publishRow(row({ costEurPerCertified: 0.000_12, pricingDigests: [DIGEST] }))
    expect(priced).toMatchObject({ costEurPerCertified: 0.000_12, pricingDigest: DIGEST })
  })

  it('publishes no cost for a row priced under two pricing tables', () => {
    const mixed = publishRow(row({ costEurPerCertified: 0.000_12, pricingDigests: [DIGEST, OTHER_DIGEST] }))
    expect(mixed).not.toHaveProperty('costEurPerCertified')
    expect(mixed).not.toHaveProperty('pricingDigest')
  })

  it('publishes no cost for a row that carries a digest but no mean, and none for a row that carries neither', () => {
    expect(publishRow(row({ pricingDigests: [DIGEST] }))).not.toHaveProperty('costEurPerCertified')
    expect(publishRow(row({ costEurPerCertified: 0.5 }))).not.toHaveProperty('pricingDigest')
  })

  it('carries the composition digest through and leaves it absent for a row that states none', () => {
    expect(publishRow(row({ compositionSha256: COMPOSITION })).compositionSha256).toBe(COMPOSITION)
    expect(publishRow(row())).not.toHaveProperty('compositionSha256')
  })

  it('states the tamper axis as not instrumented, tampered, or none', () => {
    expect(publishRow(row({ runs: 0, errors: 2, certified: 0, certificateRate: 0 })).tamper).toBe('not-instrumented')
    expect(publishRow(row({ tampered: 1 })).tamper).toBe('tampered')
    expect(publishRow(row()).tamper).toBe('none')
  })

  it('keeps the district of a districted row and states none for a row outside every district', () => {
    expect(publishRow(row({ district: 'proving-ground' })).district).toBe('proving-ground')
    expect(publishRow(row())).not.toHaveProperty('district')
  })
})

describe('rankable', () => {
  it('keeps a verdict whose two arm routes both appear in the published rows', () => {
    const rows = [row({ model: 'left' }), row({ model: 'right' })]
    expect(rankable([experiment('left', 'right', 'promote')], rows)).toHaveLength(1)
  })

  it('drops a verdict about a route the page does not publish', () => {
    const rows = [row({ model: 'left' })]
    expect(rankable([experiment('left', 'withheld', 'promote')], rows)).toEqual([])
    expect(rankable([experiment('withheld', 'left', 'promote')], rows)).toEqual([])
  })
})

describe('publishDocument', () => {
  it('publishes the rows and rankings of a current fold', () => {
    const document = publishDocument(
      snapshot({
        rows: [row({ model: 'left' }), row({ model: 'right' })],
        experiments: [experiment('left', 'right', 'inconclusive')],
      }),
      1_000_500,
      60_000,
    )
    expect(document).toMatchObject({ version: 1, stale: false, staleAfterMs: 60_000, refreshIntervalMs: 900_000 })
    expect(document.rows).toHaveLength(2)
    expect(document.rankings).toEqual([{
      digest: 'f'.repeat(64),
      baseline: { provider: 'cli-mock', model: 'left' },
      candidate: { provider: 'cli-mock', model: 'right' },
      delta: 0.25,
      verdict: 'inconclusive',
    }])
  })

  it('publishes no ranking for a fold that carries no experiment verdict', () => {
    const document = publishDocument(snapshot({ rows: [row()] }), 1_000_500, 60_000)
    expect(document.rankings).toEqual([])
    expect(document.rows).toHaveLength(1)
  })

  it('publishes no row and no ranking once the fold is stale, and keeps the withheld counts', () => {
    const stale = publishDocument(
      snapshot({ rows: [row()], experiments: [experiment('cli-mock', 'cli-mock', 'promote')] }),
      1_000_000 + 60_001,
      60_000,
    )
    expect(stale).toMatchObject({ stale: true, rows: [], rankings: [] })
    expect(stale.withheld).toEqual({ districts: [], districtRows: 0, districtSessions: 0, heldOutRows: 0, heldOutSessions: 0 })
  })

  it('states no newest session for a fold that read none', () => {
    const { newestSessionAt: _absent, ...empty } = snapshot()
    expect(publishDocument(empty, 1_000_500, 60_000)).not.toHaveProperty('newestSessionAt')
  })
})

/**
 * The HTML face: the honest column set in one table, `resolved` and `parity`
 * under their own headings, `pending` where no composition digest covers a row,
 * the no-ranking sentence where no verdict earns a ranking, and the staleness
 * notice in place of every figure once the fold is too old.
 */

import { describe, expect, it } from 'vitest'
import {
  duration,
  escapeHtml,
  NO_RANKING_SENTENCE,
  publishDocument,
  renderHtml,
  STALE_SENTENCE,
} from '@deepseek-ai/dsh-observatory'
import { experiment, row, snapshot } from './row.ts'

const DIGEST = 'a'.repeat(64)
const COMPOSITION = 'c'.repeat(64)

/** The page one snapshot renders at the given instant against a one-minute threshold. */
function page(overrides: Parameters<typeof snapshot>[0] = {}, now = 1_000_500): string {
  return renderHtml(publishDocument(snapshot(overrides), now, 60_000))
}

describe('escapeHtml', () => {
  it('escapes every HTML-significant character of a logged value', () => {
    expect(escapeHtml(`<a href="x">&'`)).toBe('&lt;a href=&quot;x&quot;&gt;&amp;&#39;')
  })
})

describe('duration', () => {
  it('states a duration in the largest whole unit that divides it', () => {
    expect(duration(7_200_000)).toBe('2 h')
    expect(duration(900_000)).toBe('15 min')
    expect(duration(90_000)).toBe('90 s')
    expect(duration(1500)).toBe('1500 ms')
  })
})

describe('renderHtml', () => {
  it('names the fold time, the newest folded session, and the batch refresh interval', () => {
    const html = page({ rows: [row()] })
    expect(html).toContain('Folded at 1970-01-01T00:16:40.500Z.')
    expect(html).toContain('Newest folded session: 1970-01-01T00:16:40.000Z.')
    expect(html).toContain('Batch refresh interval: 15 min.')
    expect(html).toContain('Stale after 1 min.')
  })

  it('publishes resolved and parity as two columns under their own names', () => {
    const html = page({ rows: [row({ runs: 4, certified: 1, certificateRate: 0.25, parity: 0.75 })] })
    expect(html).toContain('<th scope="col">Resolved</th>')
    expect(html).toContain('<th scope="col">Parity</th>')
    expect(html).toContain('<td>25.0 % (1/4)</td>')
    expect(html).toContain('<td>75.0 %</td>')
    // The two never collapse into the figure a merged score would print.
    expect(html).not.toContain('50.0 %')
  })

  it('states none where a row measured no cases and no run where a row recorded none', () => {
    const html = page({ rows: [row({ runs: 0, errors: 2, certified: 0, certificateRate: 0 })] })
    expect(html).toContain('<td>no run</td>')
    expect(html).toContain('<td>not instrumented</td>')
    expect(html).toContain('<td>none</td>')
  })

  it('prints pending where no composition digest covers the row and the digest where one does', () => {
    expect(page({ rows: [row()] })).toContain('<td>pending</td>')
    expect(page({ rows: [row({ compositionSha256: COMPOSITION })] })).toContain(`<td>${COMPOSITION}</td>`)
  })

  it('prints the certificate executor of the row and names a row that certified nothing', () => {
    expect(page({ rows: [row()] })).toContain('<td>runner</td>')
    expect(page({ rows: [row({ certificateExecutors: [] })] })).toContain('<td>no certificate</td>')
  })

  it('prints the tampered sessions of a row beside its runs', () => {
    expect(page({ rows: [row({ runs: 4, tampered: 1 })] })).toContain('<td>tampered 1 of 4</td>')
    expect(page({ rows: [row()] })).toContain('<td>no tamper</td>')
  })

  it('prints the cost beside its pricing digest and states nothing where the rule withholds it', () => {
    const priced = page({ rows: [row({ costEurPerCertified: 0.000_12, pricingDigests: [DIGEST] })] })
    expect(priced).toContain(`<td>€0.000120 · ${DIGEST}</td>`)
    expect(page({ rows: [row()] })).toContain('<td>not published</td>')
  })

  it('prints the no-ranking sentence until a verdict earns a ranking', () => {
    expect(page({ rows: [row()] })).toContain(escapeHtml(NO_RANKING_SENTENCE))
    const ranked = page({
      rows: [row({ model: 'left' }), row({ model: 'right' })],
      experiments: [experiment('left', 'right', 'promote')],
    })
    expect(ranked).not.toContain(escapeHtml(NO_RANKING_SENTENCE))
    expect(ranked).toContain('cli-mock/left versus cli-mock/right')
    expect(ranked).toContain('<strong>promote</strong>')
  })

  it('states what withholding removed from a current page', () => {
    const html = renderHtml(publishDocument({
      ...snapshot({ rows: [row()] }),
      withheld: { districts: ['workshop'], districtRows: 1, districtSessions: 4, heldOutRows: 2, heldOutSessions: 3 },
    }, 1_000_500, 60_000))
    expect(html).toContain('Withheld districts: workshop.')
    expect(html).toContain('District rows withheld: 1 (4 sessions).')
    expect(html).toContain('Held-out rows withheld: 2 (3 sessions).')
    expect(renderHtml(publishDocument(snapshot({ rows: [row()] }), 1_000_500, 60_000)))
      .toContain('Withheld districts: none.')
  })

  it('names an empty fold rather than printing a table with no row', () => {
    expect(page()).toContain('No row survived this fold')
  })

  it('replaces every figure with the staleness notice once the fold is too old', () => {
    const stale = page({
      rows: [row({ runs: 4, certified: 1, certificateRate: 0.25, parity: 0.75, costEurPerCertified: 0.000_12, pricingDigests: [DIGEST] })],
      experiments: [experiment('cli-mock', 'cli-mock', 'promote')],
    }, 1_000_000 + 60_001)
    expect(stale).toContain(escapeHtml(STALE_SENTENCE))
    expect(stale).not.toContain('<table>')
    expect(stale).not.toContain('25.0 %')
    expect(stale).not.toContain('75.0 %')
    expect(stale).not.toContain(DIGEST)
    expect(stale).not.toContain('promote')
    // The provenance the notice is about survives, so a reader can see how old the page is.
    expect(stale).toContain('Newest folded session: 1970-01-01T00:16:40.000Z.')
  })

  it('states that no session was folded when the store held none', () => {
    const { newestSessionAt: _absent, ...empty } = snapshot()
    expect(renderHtml(publishDocument(empty, 1_000_500, 60_000))).toContain('No session was folded.')
  })

  it('references no external resource and carries both themes through one token set', () => {
    const html = page({ rows: [row()] })
    expect(html).not.toMatch(/(?:src|href)=/)
    expect(html).toContain('@media (prefers-color-scheme:dark)')
    expect(html).toContain('font-variant-numeric:tabular-nums')
  })

  it('escapes a logged value that spells markup', () => {
    expect(page({ rows: [row({ environmentId: 'smoke:<script>' })] })).toContain('<td>smoke:&lt;script&gt;</td>')
  })
})

/**
 * `ctx.observatory` over a real persistence backend and a real scorekeeper: one
 * fold over every persisted session, the configured districts and the held-out
 * split withheld from the public rows and counted, the newest folded session's
 * creation time recorded, and both faces rendered from the same snapshot.
 */

import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import SessionStore, { SESSION_FORMAT_VERSION, SessionId } from '@deepseek-ai/dsh-session'
import type { SessionEvent, SessionHeader } from '@deepseek-ai/dsh-session'
import JsonlSessionPersistence from '@deepseek-ai/dsh-session-persistence-jsonl'
import ScorekeeperService from '@deepseek-ai/dsh-scorekeeper'
import ObservatoryService from '@deepseek-ai/dsh-observatory'
import { experiment } from './row.ts'

const roots: string[] = []

afterEach(async () => {
  await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true })))
})

/** The store, a JSONL backend under a fresh root, the scorekeeper, and the observatory. */
async function harness(): Promise<Context> {
  const root = await mkdtemp(join(tmpdir(), 'dsh-observatory-'))
  roots.push(root)
  const ctx = new Context()
  await ctx.plugin(SessionStore)
  await ctx.plugin(JsonlSessionPersistence, { root, compression: 'none' })
  await ctx.plugin(ScorekeeperService, { passAtK: [1] })
  await ctx.plugin(ObservatoryService, {
    withhold: { districts: ['workshop'], heldOut: true },
    staleAfterMs: 60_000,
    refreshIntervalMs: 900_000,
  })
  return ctx
}

/** One stamped, certified session log on the named route, district, and split. */
function log(options: {
  readonly model: string
  readonly district?: string
  readonly heldOut?: boolean
}): SessionEvent[] {
  const events: { type: string; data: unknown }[] = [
    {
      type: 'environment/run',
      data: {
        kind: 'environment/run',
        version: 1,
        environmentId: 'smoke:round-trip',
        environmentKind: 'smoke',
        heldOut: options.heldOut ?? false,
        promptSha256: 'c'.repeat(64),
        checksSha256: 'c'.repeat(64),
        contentSha256: 'c'.repeat(64),
        repetition: 0,
        ...options.district === undefined ? {} : { district: options.district },
        model: { provider: 'cli-mock', model: options.model },
        isolation: 'none',
      },
    },
    {
      type: 'goal/change',
      data: {
        kind: 'goal/change',
        version: 1,
        operation: 'create',
        goal: { id: 'goal-1', revision: 1, objective: 'Prove the fold', phase: 'active', maxGoalRounds: 7 },
        roundsStarted: 0,
        createdAt: 10,
        updatedAt: 11,
      },
    },
    {
      type: 'verification/standard',
      data: {
        kind: 'verification/standard',
        version: 1,
        operation: 'author',
        standard: {
          id: 'standard-1',
          revision: 1,
          goalId: 'goal-1',
          checks: [{ id: 'round-trip', outcome: 'the round trip prints', run: 'printf X' }],
          relaxed: [],
        },
        createdAt: 11,
        updatedAt: 11,
      },
    },
    {
      type: 'verification/run',
      data: {
        kind: 'verification/run',
        version: 1,
        standard: { id: 'standard-1', revision: 1 },
        attempt: 1,
        isolation: 'none',
        executor: 'runner',
        verdict: 'passed',
        results: [{ checkId: 'round-trip', status: 'pass', evidence: 'pass round-trip' }],
        recordedAt: 21,
      },
    },
    {
      type: 'verification/certificate',
      data: {
        kind: 'verification/certificate',
        version: 1,
        certificate: {
          standard: { id: 'standard-1', revision: 1 },
          goalId: 'goal-1',
          isolation: 'none',
          executor: 'runner',
          results: [{ checkId: 'round-trip', status: 'pass', evidence: 'pass round-trip' }],
          recordedAt: 30,
        },
      },
    },
  ]
  return events.map((event, index) => ({ ...event, seq: index, time: 1000 + index }) as unknown as SessionEvent)
}

/** Store one session's header and log under the backend. */
async function persist(ctx: Context, id: string, createdAt: number, events: SessionEvent[]): Promise<void> {
  const meta: SessionHeader = { version: SESSION_FORMAT_VERSION, id: SessionId(id), createdAt }
  await ctx.sessionPersistence.create(meta)
  await ctx.sessionPersistence.append(meta.id, events)
}

describe('ObservatoryService', () => {
  it('folds every persisted session, withholds the configured districts and the held-out split, and counts both', async () => {
    const ctx = await harness()
    await persist(ctx, 'public-0', 4000, log({ model: 'public' }))
    await persist(ctx, 'workshop-0', 5000, log({ model: 'client', district: 'workshop' }))
    await persist(ctx, 'reserved-0', 3000, log({ model: 'public', heldOut: true }))

    const snapshot = await ctx.observatory.snapshot()
    expect(snapshot.rows.map(row => [row.model, row.district, row.heldOut])).toEqual([['public', undefined, false]])
    expect(snapshot.withheld).toEqual({
      districts: ['workshop'],
      districtRows: 1,
      districtSessions: 1,
      heldOutRows: 1,
      heldOutSessions: 1,
    })
    expect(snapshot).toMatchObject({ sessions: 3, unstamped: 0, skipped: [], refreshIntervalMs: 900_000 })
    // The newest folded header decides staleness, whichever district it came from.
    expect(snapshot.newestSessionAt).toBe(5000)
    expect(snapshot.foldedAt).toBeGreaterThan(0)
    await ctx.fiber.dispose()
  })

  it('states no newest session and publishes nothing for an empty store', async () => {
    const ctx = await harness()
    const snapshot = await ctx.observatory.snapshot()
    expect(snapshot).not.toHaveProperty('newestSessionAt')
    expect(snapshot.rows).toEqual([])
    expect(ctx.observatory.render(snapshot, 0).json.stale).toBe(true)
    await ctx.fiber.dispose()
  })

  it('renders both faces of one publication from the same snapshot', async () => {
    const ctx = await harness()
    await persist(ctx, 'public-0', 4000, log({ model: 'public' }))
    const snapshot = await ctx.observatory.snapshot()
    const page = ctx.observatory.render(snapshot, 4000 + 60_000)
    expect(page.json).toMatchObject({ stale: false, staleAfterMs: 60_000, refreshIntervalMs: 900_000 })
    expect(page.json.rows.map(row => row.model)).toEqual(['public'])
    expect(page.html).toContain('cli-mock/public')
    expect(ctx.observatory.render(snapshot, 4000 + 60_001).json.stale).toBe(true)
    await ctx.fiber.dispose()
  })

  it('publishes only the verdicts whose two arm routes both survive withholding', async () => {
    const ctx = await harness()
    await persist(ctx, 'left-0', 4000, log({ model: 'left' }))
    await persist(ctx, 'right-0', 4100, log({ model: 'right' }))
    await persist(ctx, 'workshop-0', 4200, log({ model: 'client', district: 'workshop' }))

    const published = await ctx.observatory.snapshot({
      experiments: [experiment('left', 'right', 'promote'), experiment('left', 'client', 'promote')],
    })
    expect(published.experiments.map(result => result.arms.candidate.model.model)).toEqual(['right'])
    expect((await ctx.observatory.snapshot()).experiments).toEqual([])
    await ctx.fiber.dispose()
  })
})

