    smoke('smoke:reserved', 'Held out for evaluation.', { id: CheckId('round-trip-prints'), outcome: 'the bash round trip prints CLI_TOOL_ROUND_TRIP', run: 'printf CLI_TOOL_ROUND_TRIP' }, true),
  ]

